#!/usr/bin/env python3
"""只使用标准库和 Git；不运行上游脚本，不修改远端历史。"""
import argparse
import hashlib
import json
import os
from pathlib import Path
import re
import subprocess
import sys

SOURCE_STATE = '.github/upstream-sync-state'
WORKFLOW_STATE = '.github/upstream-sync/workflows-state'
PENDING = '.github/UPSTREAM_WORKFLOWS_PENDING.md'
RESERVED = [SOURCE_STATE, PENDING, '.github/upstream-sync/',
            '.github/workflows/sync-upstream.yml']
SENSITIVE = ['.github/workflows/', '.github/actions/']


class SyncError(RuntimeError):
    pass


def git(*args, data=None, check=True):
    p = subprocess.run(['git', '-c', 'core.quotePath=false', *args], input=data,
                       stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    if check and p.returncode:
        raise SyncError(f'git {args[0]} 失败：\n{p.stderr.decode("utf-8", "replace")}')
    return p


def text(*args):
    return git(*args).stdout.decode('utf-8').strip()


def valid_sha(value):
    if not re.fullmatch(r'[0-9a-f]{40}', value):
        raise SyncError('同步记录或审核版本不是完整的 40 位提交编号。')
    git('cat-file', '-e', value + '^{commit}')
    return value


def ancestor(base, target):
    if git('merge-base', '--is-ancestor', base, target, check=False).returncode:
        raise SyncError('上游历史重写或审核版本已过期；拒绝自动重置同步记录。')


def matches(path, rules):
    return any(path.startswith(x) if x.endswith('/') else path == x for x in rules)


def changed(base, target, paths=None):
    args = ['diff', '--name-only', '--no-renames', '-z', base, target]
    if paths:
        args += ['--', *paths]
    return [x.decode('utf-8') for x in git(*args).stdout.split(b'\0') if x]


def patch(base, target, paths):
    return git('diff', '--binary', '--full-index', '--no-renames',
               '--no-ext-diff', '--no-textconv', base, target, '--', *paths).stdout


def write(path, value):
    p = Path(path)
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(value, encoding='utf-8', newline='\n')


def entry(ref, path):
    return text('ls-tree', ref, '--', path)


def review(base, target):
    paths = [p for p in changed(base, target, SENSITIVE) if not matches(p, RESERVED)]
    changes = patch(base, target, paths) if paths else b''
    # 同时绑定本仓库文件的版本，避免审核后个人修改被另一轮审批覆盖。
    local = '\n'.join(entry('HEAD', p) or f'missing {p}' for p in paths).encode()
    digest = hashlib.sha256(base.encode() + b'\0' + target.encode() + b'\0' +
                            changes + b'\0' + local).hexdigest()
    return paths, changes, digest


def record_report(target, base, paths, digest):
    report = ('# Mika 上游工作流待审核\n\n'
              '<!-- Automatically generated by Sync upstream Mika -->\n'
              '状态：**源码同步完成，以下工作流尚未同步；不是完整同步成功。**\n\n'
              f'- 上游版本：`{target}`\n- 工作流基线：`{base}`\n'
              f'- 审核摘要：`{digest}`\n\n'
              '文件（含新增、修改、删除和改名）：\n\n' +
              '\n'.join(f'- `{json.dumps(p, ensure_ascii=False)[1:-1]}`' for p in paths) +
              '\n\n请先下载本次运行的 `upstream-sync-diagnostics` 产物，审核 '
              '`workflows.patch`。在本工作流手动运行时选择 `review-workflows`，'
              '填入以上完整版本和摘要；只有拥有仓库写权限的人可以发起审核应用。'
              '版本或本仓库工作流内容变化后，旧摘要失效。\n'
              '专用 GitHub App 未配置时日常源码同步照常工作，工作流审核应用会明确失败。\n')
    write(PENDING, report)
    return report


def publish(remote, branch, initial):
    # 普通推送本身提供原子式的远端并发保护。失败后不 rebase/force；重跑重新计算。
    result = git('push', remote, f'HEAD:refs/heads/{branch}', check=False)
    if result.returncode:
        # 网络在服务器接收后中断时，先核实提交是否已实际到达。
        probe = git('ls-remote', remote, f'refs/heads/{branch}', check=False)
        remote_sha = probe.stdout.decode().split()
        if remote_sha and remote_sha[0] == text('rev-parse', 'HEAD'):
            return
        raise SyncError('推送失败（权限、网络或远端分支已更新）。未强制推送；'
                        '请根据诊断信息重跑。\n' + result.stderr.decode('utf-8', 'replace'))


def run(args, result):
    if text('status', '--porcelain'):
        raise SyncError('工作区不干净；拒绝覆盖本地修改。')
    if text('rev-parse', '--is-shallow-repository') != 'false':
        raise SyncError('缺少完整历史；必须以 fetch-depth: 0 检出。')
    initial = text('rev-parse', 'HEAD')
    upstream = valid_sha(text('rev-parse', args.upstream))
    source_base = valid_sha(Path(SOURCE_STATE).read_text().strip()) if Path(SOURCE_STATE).exists() else valid_sha(text('merge-base', 'HEAD', upstream))
    workflow_base = valid_sha(Path(WORKFLOW_STATE).read_text().strip()) if Path(WORKFLOW_STATE).exists() else valid_sha(text('merge-base', 'HEAD', upstream))
    ancestor(source_base, upstream)
    ancestor(workflow_base, upstream)
    target = upstream
    if args.mode == 'review-workflows':
        target = valid_sha(args.upstream_sha)
        ancestor(target, upstream)
        if target != source_base:
            raise SyncError('审核版本必须等于已同步源码的版本；请先日常同步，再审核报告。')
        ancestor(workflow_base, target)

    result.update(upstream=target, initial_head=initial, source_base=source_base,
                  workflow_base=workflow_base, mode=args.mode)
    source_paths = changed(source_base, target)
    # 同步引擎、记录和本仓库工作流永远由本仓库维护；上游碰撞显式停止。
    collisions = [p for p in source_paths if matches(p, RESERVED)]
    if collisions:
        raise SyncError('上游修改本仓库保留路径，需要人工处理：' + repr(collisions))
    paths, workflow_patch, digest = review(workflow_base, target)
    result.update(pending_paths=paths, review_digest=digest)
    args.artifacts.mkdir(parents=True, exist_ok=True)
    (args.artifacts / 'workflows.patch').write_bytes(workflow_patch)
    if args.mode == 'review-workflows':
        if not re.fullmatch(r'[0-9a-f]{64}', args.review_digest) or args.review_digest != digest:
            raise SyncError('审核摘要不匹配；版本、补丁或本仓库文件已变化，拒绝应用旧审核。')
        selected_patch = workflow_patch
    else:
        ordinary = [p for p in source_paths if not matches(p, SENSITIVE + RESERVED)]
        selected_patch = patch(source_base, target, ordinary) if ordinary else b''
    (args.artifacts / 'selected.patch').write_bytes(selected_patch)
    if selected_patch:
        applied = git('apply', '--3way', '--index', '--whitespace=nowarn',
                      '-', data=selected_patch, check=False)
        (args.artifacts / 'apply.log').write_bytes(applied.stderr)
        if applied.returncode:
            (args.artifacts / 'conflicts.txt').write_text(text('diff', '--name-only', '--diff-filter=U'), encoding='utf-8')
            (args.artifacts / 'conflicted.diff').write_bytes(git('diff').stdout)
            raise SyncError('上游与个人修改冲突；未提交、未推送、未推进同步记录。现场见诊断产物。')

    if args.mode == 'review-workflows':
        write(WORKFLOW_STATE, target + '\n')
        if Path(PENDING).exists():
            Path(PENDING).unlink()
        result['pending_paths'] = []
    else:
        write(SOURCE_STATE, target + '\n')
        # 没有敏感差异即可推进工作流基线，避免未来重新检查无关历史。
        write(WORKFLOW_STATE, (workflow_base if paths else target) + '\n')
        if paths:
            report = record_report(target, workflow_base, paths, digest)
            (args.artifacts / 'pending.md').write_text(report, encoding='utf-8')
        elif Path(PENDING).exists():
            Path(PENDING).unlink()

    git('add', '--', SOURCE_STATE, '.github/upstream-sync/')
    # add -A 仅覆盖本脚本负责的报告，不能混入工作区其他文件。
    if Path(PENDING).exists() or git('ls-files', '--', PENDING).stdout:
        git('add', '-A', '--', PENDING)
    git('diff', '--cached', '--check')
    staged = text('diff', '--cached', '--name-only')
    if args.mode == 'source' and any(matches(p, SENSITIVE) for p in staged.splitlines()):
        raise SyncError('日常同步意外包含工作流，拒绝提交。')
    has_changes = bool(staged)
    if has_changes and not args.dry_run:
        git('config', 'user.name', 'github-actions[bot]')
        git('config', 'user.email', '41898282+github-actions[bot]@users.noreply.github.com')
        label = 'Review upstream workflows' if args.mode == 'review-workflows' else 'Sync upstream Mika source'
        git('commit', '-m', f'{label} to {target[:12]}')
    result.update(changed=has_changes, commit=text('rev-parse', 'HEAD'),
                  status='pending_review' if result['pending_paths'] else 'complete',
                  dry_run=args.dry_run, pushed=False)
    if args.push and not args.dry_run and has_changes:
        publish(args.remote, args.branch, initial)
        result['pushed'] = True


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--mode', choices=['source', 'review-workflows'], default='source')
    parser.add_argument('--upstream', default='upstream/main')
    parser.add_argument('--upstream-sha', default='')
    parser.add_argument('--review-digest', default='')
    parser.add_argument('--artifacts', type=Path, required=True)
    parser.add_argument('--push', action='store_true')
    parser.add_argument('--dry-run', action='store_true')
    parser.add_argument('--remote', default='origin')
    parser.add_argument('--branch', default='main')
    args = parser.parse_args()
    result = {'status': 'failed', 'pending_paths': [], 'mode': args.mode}
    code = 0
    try:
        run(args, result)
    except (SyncError, OSError, UnicodeError) as exc:
        result.update(status='failed', error=str(exc))
        print(str(exc), file=sys.stderr)
        code = 1
    finally:
        args.artifacts.mkdir(parents=True, exist_ok=True)
        (args.artifacts / 'result.json').write_text(json.dumps(result, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
        state = text('status', '--porcelain')
        (args.artifacts / 'git-status.txt').write_text(state + '\n', encoding='utf-8')
        summary = ('# Mika 上游同步结果\n\n' +
                   {'failed': '**失败，不能视为同步成功。**',
                    'pending_review': '**源码同步完成；工作流待审核，尚未完整同步。**',
                    'complete': '**同步完成。**'}[result['status']] + '\n\n' +
                   f'诊断信息：`upstream-sync-diagnostics`。\n\n'
                   f'上游版本：`{result.get("upstream", "未知")}`\n\n' +
                   (f'错误：{result["error"]}\n' if 'error' in result else '') +
                   (f'待审核文件数：{len(result["pending_paths"])}；审核摘要：`{result.get("review_digest", "")}`\n' if result['pending_paths'] else ''))
        (args.artifacts / 'summary.md').write_text(summary, encoding='utf-8')
        if os.getenv('GITHUB_STEP_SUMMARY'):
            with open(os.environ['GITHUB_STEP_SUMMARY'], 'a', encoding='utf-8') as f:
                f.write(summary)
        if os.getenv('GITHUB_OUTPUT'):
            with open(os.environ['GITHUB_OUTPUT'], 'a', encoding='utf-8') as f:
                f.write(f'status={result["status"]}\npending={str(bool(result["pending_paths"])).lower()}\n')
    return code


if __name__ == '__main__':
    sys.exit(main())
